def transform(grid):
    # Fill the gaps along the outer rectangular frame with color 2,
    # keeping the original colored markers intact.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    r0 = min(r for r, c in marks)
    r1 = max(r for r, c in marks)
    c0 = min(c for r, c in marks)
    c1 = max(c for r, c in marks)
    out = [row[:] for row in grid]
    for c in range(c0, c1 + 1):
        if out[r0][c] == bg:
            out[r0][c] = 2
        if out[r1][c] == bg:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if out[r][c0] == bg:
            out[r][c0] = 2
        if out[r][c1] == bg:
            out[r][c1] = 2
    return out

